import json
d=json.load(open(var_call_5))
P={x['_id']:x for x in d}
res={}
def walk(p,depth):
    for b in P[p].get('bom') or []:
        if b['end_date'] not in ('None',None): continue
        c=b['component_number']; x=P.get(c)
        if x is None: res[c]=('missing',depth); continue
        lts=[float(v['average_lead_time']) for v in x.get('vendors') or [] if v.get('average_lead_time') not in (None,'None')]
        if x['make_flag'] in ('0',0,False) or lts:
            res[c]=(x['name'],x['make_flag'],lts,depth)
        walk(c,depth+1)
walk('BK-M68B-38',1)
print("__RESULT__:")
print(json.dumps(res))
